export function reviewedMentionLocations(saintId: string): { book: number; page: number }[] {
  return mentions.filter(item => (item.saintIds as readonly string[]).includes(saintId)).map(item => ({ book: item.book, page: item.page }));
}

export function reviewedMentionForPage(saintId: string, book: number, page: number, sha: string, body: string): { book: number; page: number } | undefined {
  const item = mentions.find(record => record.book === book && record.page === page && record.sourceSha256 === sha && (record.saintIds as readonly string[]).includes(saintId));
  if (!item) return undefined;
  const offset = body.indexOf(item.anchor);
  return offset >= 0 && body.indexOf(item.anchor, offset + 1) === -1 ? { book, page } : undefined;
}

/** Immutable editorial records for checksum-aware corpus audits. */
export function reviewedMentionRecords() { return mentions; }
